'use strict';
// GOLD CANDLE DNA — sequence miner, not indicator optimization.
// DEV discovers recurring symbolic candle sequences; HOLD is untouched validation.
const fs=require('fs'),raw=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=raw.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
const A=Array(N).fill(NaN);for(let i=14;i<N;i++){let s=0;for(let j=i-13;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));A[i]=s/14}
function token(i){let b=M[i],a=A[i],r=b.h-b.l;if(!a||r<=0)return'X';let body=(b.c-b.o)/a,sz=r/a,cp=(b.c-b.l)/r,dir=body>.08?'B':body<-.08?'S':'N',mag=sz<.65?'s':sz<1.25?'m':'L',pos=cp>.7?'H':cp<.3?'L':'M';return dir+mag+pos}
const T=M.map((_,i)=>token(i));
function outcome(i,side,rr=1.5,slA=1,hold=10){if(i+1>=N||!A[i])return null;let en=M[i+1].o,sl=side==='BUY'?en-slA*A[i]:en+slA*A[i],tp=side==='BUY'?en+rr*slA*A[i]:en-rr*slA*A[i];for(let j=i+1;j<=Math.min(N-1,i+hold);j++){let b=M[j];if(side==='BUY'){if(b.l<=sl)return-1;if(b.h>=tp)return rr}else{if(b.h>=sl)return-1;if(b.l<=tp)return rr}}let p=M[Math.min(N-1,i+hold)].c;return side==='BUY'?(p-en)/(en-sl):(en-p)/(sl-en)}
function stats(a){let w=0,g=0,l=0,e=0,p=0,d=0;for(let r of a){e+=r;if(r>0){w++;g+=r}else l-=r;p=Math.max(p,e);d=Math.max(d,p-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:l?g/l:g?99:0,net:e,dd:d}}
function mine(L,H,len){let map=new Map;for(let i=Math.max(60,L+len-1);i<Math.min(H-11,N-11);i++){let key=T.slice(i-len+1,i+1).join('-');if(key.includes('X'))continue;let z=map.get(key);if(!z)map.set(key,z={BUY:[],SELL:[]}),z=map.get(key);z.BUY.push(outcome(i,'BUY'));z.SELL.push(outcome(i,'SELL'))}return map}
function evalHold(key,len,side){let a=[];for(let i=Math.max(C+len-1,60);i<N-11;i++)if(T.slice(i-len+1,i+1).join('-')===key)a.push(outcome(i,side));return stats(a)}
let all=[];for(let len of [4,5]){let mp=mine(0,C,len);for(let [key,z] of mp)for(let side of ['BUY','SELL']){let d=stats(z[side]);if(d.n>=45)all.push({len,key,side,d})}}
all.sort((a,b)=>(b.d.pf-a.d.pf)||(b.d.wr-a.d.wr));console.log(`GOLD CANDLE DNA MINER | M5=${N} | DEV75/HOLD25 | patterns=${all.length}`);console.log('\nTOP 30 DISCOVERED ON DEV -> UNTOUCHED HOLD');all.slice(0,30).forEach((x,k)=>{let h=evalHold(x.key,x.len,x.side);console.log(`${k+1} L${x.len} ${x.side} ${x.key} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)}`)});
console.log('\nDNA SURVIVORS | DEV T>=45 PF>=1.35 WR>=55 | HOLD T>=12 PF>=1.25 WR>=52');let Z=all.map(x=>({x,h:evalHold(x.key,x.len,x.side)})).filter(z=>z.x.d.pf>=1.35&&z.x.d.wr>=55&&z.h.n>=12&&z.h.pf>=1.25&&z.h.wr>=52);if(!Z.length)console.log('NONE — no stable DNA edge under these strict rules.');else Z.slice(0,20).forEach((z,k)=>console.log(`${k+1} L${z.x.len} ${z.x.side} ${z.x.key} | DEV T${z.x.d.n} WR${z.x.d.wr.toFixed(1)} PF${z.x.d.pf.toFixed(2)} | HOLD T${z.h.n} WR${z.h.wr.toFixed(1)} PF${z.h.pf.toFixed(2)}`));